[
  {
    "ae_welfare_concern": "doesn't deserve to be crushed either",
    "pd_decision_conflict": "it sits heavy on me right now",
    "sys_rule_justification": "rule I was taught, that you don't use a person as a means"
  },
  {
    "ae_welfare_concern": "their families, all that loss, it's unbearable to picture",
    "ce_understood_harm": "pulling this lever means I'm the one who kills the single man",
    "pd_decision_conflict": "I keep thinking there's something wrong about choosing who dies",
    "sys_rule_justification": "raised to believe you don't take an action that directly ends someone's life",
    "pda_responsibility": "I'm the one who kills the single man"
  },
  {
    "ae_welfare_concern": "The five on the far track... that thought makes me sick",
    "pd_decision_conflict": "Both outcomes carry a grief I can't shake off easily",
    "sys_rule_justification": "principle about not making yourself the direct cause of someone's death"
  },
  {
    "ae_welfare_concern": "The single worker matters",
    "ce_understood_harm": "someone's life ends because of what I do or fail to do",
    "pd_decision_conflict": "weighs on me more than I can say",
    "sys_rule_justification": "taught that harming someone directly is different from allowing harm",
    "pda_responsibility": "someone's life ends because of what I do or fail to do here"
  },
  {
    "ae_welfare_concern": "watching five people suffer if I do nothing tears at me too",
    "pd_decision_conflict": "My hands feel frozen on this lever",
    "sys_rule_justification": "believed you shouldn't actively cause a death"
  },
  {
    "ae_welfare_concern": "their suffering matters just as much",
    "ce_understood_harm": "that one man's life ends because of my choice",
    "pd_decision_conflict": "It's hard to breathe thinking about this",
    "sys_rule_justification": "pulling someone into a fatal path myself is different from failing to prevent",
    "pda_self_consequence_regret": "that guilt would follow me forever",
    "pda_responsibility": "that one man's life ends because of my choice"
  },
  {
    "ae_welfare_concern": "their pain and loss would be devastating",
    "pd_decision_conflict": "I feel sick either way",
    "sys_rule_justification": "some duty not to actively cause his death"
  },
  {
    "ae_welfare_concern": "spare five others whose suffering I do care about",
    "ce_understood_harm": "know exactly what the train would do to him",
    "pd_decision_conflict": "This is heavier than anything I've had to face",
    "sys_rule_justification": "moral line about not being the direct instrument of someone's death"
  },
  {
    "pd_decision_conflict": "My mind keeps going back and forth",
    "sys_rule_justification": "deliberately causing one person's death isn't the same as failing to prevent another's",
    "pda_responsibility": "if I don't act their deaths are on me"
  },
  {
    "ae_welfare_concern": "The five further down matter just as much to me",
    "ce_understood_harm": "The single worker's death, if I switch it, would be something I caused",
    "pd_decision_conflict": "I feel sick standing here with this decision in my hands",
    "sys_rule_justification": "any rule I was taught about right and wrong",
    "pda_responsibility": "something I caused directly"
  }
]
